// `pltt dev` serves the simulator on localhost — the CLI bundler hardcodes
// NODE_ENV="production" for palette-app frameworks, so we detect the dev
// host at runtime instead of trusting the build-time flag.
const isDevHost =
  typeof window !== "undefined" &&
  /^(localhost|127\.0\.0\.1|0\.0\.0\.0)$/.test(window.location.hostname)

const devModels = isDevHost
  ? [
    {
      label: "Flux",
      value: "flux_schnell",
      description: "Fast processing with incredible sharp detail",
      version: "Schnell",
      icon: FluxColorfulIcon,
      color: "#F97316",
      options: ["HD", "Text to Image", "Image to Image"],
      reference: false,
    },
  ]
  : []

